public class Main {
    public static void main(String[] args) {
        // Start at the loader that loaded Main and walk up through the parents
        ClassLoader l = Main.class.getClassLoader();
        while (l != null) {
            System.out.println("loader: " + l.getName());
            l = l.getParent();
        }
        System.out.println("(parent of platform is null = bootstrap)");
        // Core classes come from the bootstrap loader, which shows up as null
        System.out.println("String loaded by: " + String.class.getClassLoader());
        // java.sql is a JDK module outside java.base: platform loader
        System.out.println("java.sql.Driver loaded by: "
                + java.sql.Driver.class.getClassLoader().getName());
        System.out.println("Main loaded by: " + Main.class.getClassLoader().getName());
    }
}

public class Main {
    static class Bad {
        // This static initializer throws, so class initialization fails
        static int v = Integer.parseInt("zero");
    }

    public static void main(String[] args) {
        // ClassNotFoundException: asked for a class by name, nobody has it
        try {
            Class.forName("com.example.Missing");
        } catch (ClassNotFoundException e) {
            System.out.println("1) " + e.getClass().getSimpleName() + ": " + e.getMessage());
        }
        // First use of Bad runs <clinit>, which fails
        try {
            System.out.println(Bad.v);
        } catch (Throwable t) {
            System.out.println("2) " + t.getClass().getSimpleName()
                    + " caused by " + t.getCause().getClass().getSimpleName());
        }
        // Second use: the class is marked erroneous, no retry
        try {
            System.out.println(Bad.v);
        } catch (Throwable t) {
            System.out.println("3) " + t.getClass().getSimpleName() + ": " + t.getMessage());
        }
    }
}

public class Main {
    static class Foo {
        static final int K = 5;                 // compile-time constant
        static final java.util.List<String> L = java.util.List.of("a"); // not a constant
        static { System.out.println("  >> Foo initialized"); }
        static void hello() { System.out.println("  hello()"); }
    }

    public static void main(String[] args) {
        System.out.println("Foo.class literal:");
        Class<?> c = Foo.class;                 // loads, does NOT initialize
        System.out.println("array creation:");
        Foo[] arr = new Foo[2];                 // does NOT initialize
        System.out.println("read constant K = " + Foo.K); // inlined by javac
        System.out.println("read List L:");
        System.out.println("  " + Foo.L);       // first active use: init runs once
        System.out.println("call hello():");
        Foo.hello();                            // already initialized, no second run
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Locals: slot 0 = a, slot 1 = b.  Computes a * b + 2
        int[] locals = {3, 4};
        String[] code = {"iload 0", "iload 1", "imul", "iconst 2", "iadd"};
        Deque<Integer> stack = new ArrayDeque<>();   // the operand stack
        for (String ins : code) {
            String[] p = ins.split(" ");
            switch (p[0]) {
                case "iload": stack.push(locals[Integer.parseInt(p[1])]); break;
                case "iconst": stack.push(Integer.parseInt(p[1])); break;
                case "imul": stack.push(stack.pop() * stack.pop()); break;
                case "iadd": stack.push(stack.pop() + stack.pop()); break;
            }
            System.out.println(ins + "  -> stack " + stack);
        }
        System.out.println("a*b+2 = " + stack.pop());
        // i = i++ : iload i, iinc i, istore i  (old value is stored back)
        int i = 5;
        i = i++;
        System.out.println("i = i++ gives " + i);
    }
}

public class Main {
    interface Shape { int area(); }
    static class Circle implements Shape { public int area() { return 3; } }
    static class Square implements Shape { public int area() { return 4; } }
    static class Tri implements Shape { public int area() { return 5; } }

    // One call site: s.area(). The JIT profiles which classes reach it.
    static long total(Shape[] shapes) {
        long sum = 0;
        for (Shape s : shapes) sum += s.area();
        return sum;
    }

    public static void main(String[] args) {
        Shape[] mono = new Shape[3000], mixed = new Shape[3000];
        for (int i = 0; i < 3000; i++) {
            mono[i] = new Circle();                       // 1 receiver type
            mixed[i] = i % 3 == 0 ? new Circle() : i % 3 == 1 ? new Square() : new Tri();
        }
        long a = 0, b = 0;
        for (int r = 0; r < 200; r++) { a += total(mono); }
        System.out.println("monomorphic sum = " + a);
        // After 3+ types the site is megamorphic: no inlining, a vtable call
        for (int r = 0; r < 200; r++) { b += total(mixed); }
        System.out.println("megamorphic sum = " + b);
        // Try: java -XX:+PrintCompilation Main  and watch the compile events
    }
}

import java.util.*;

public class Main {
    static class Point {
        final int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    // p never leaves this method: C2 can replace it with two ints
    static long noEscape(int n) {
        long s = 0;
        for (int i = 0; i < n; i++) {
            Point p = new Point(i, i + 1);
            s += p.x + p.y;
        }
        return s;
    }

    // p is stored in a list, so it escapes and must be a real object
    static long escapes(int n, List<Point> keep) {
        long s = 0;
        for (int i = 0; i < n; i++) {
            Point p = new Point(i, i + 1);
            keep.add(p);
            s += p.x + p.y;
        }
        return s;
    }

    public static void main(String[] args) {
        System.out.println("noEscape(1000) = " + noEscape(1000));
        List<Point> keep = new ArrayList<>();
        System.out.println("escapes(1000)  = " + escapes(1000, keep));
        System.out.println("objects kept alive: " + keep.size());
    }
}

public class Main {
    static int depth = 0;

    // Every call pushes a frame on this thread's stack
    static void recurse() {
        depth++;
        recurse();
    }

    public static void main(String[] args) {
        int local = 42;                        // primitive local: lives in the frame
        int[] big = new int[1_000_000];        // the array is on the heap, ref is a local
        System.out.println("local = " + local + ", heap array length = " + big.length);
        try {
            recurse();
        } catch (StackOverflowError e) {
            // Stack is small (about 512 KB to 1 MB by default); heap is large
            System.out.println("StackOverflowError caught");
            System.out.println("depth reached > 1000: " + (depth > 1000));
        }
        // Heap has its own limit and its own error
        System.out.println("max heap is positive: " + (Runtime.getRuntime().maxMemory() > 0));
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Object graph: node -> nodes it references
        Map<Integer, int[]> refs = new HashMap<>();
        refs.put(0, new int[]{1});      // 0 is referenced by a root (a local variable)
        refs.put(1, new int[]{2});
        refs.put(2, new int[]{1});      // 1 <-> 2 cycle, but reachable from the root
        refs.put(3, new int[]{4});
        refs.put(4, new int[]{3});      // 3 <-> 4 cycle, unreachable: garbage
        refs.put(5, new int[]{});       // nothing points to 5: garbage
        int[] roots = {0};
        System.out.println("roots: " + Arrays.toString(roots));

        // Tracing: mark everything reachable from the roots
        Set<Integer> marked = new TreeSet<>();
        Deque<Integer> todo = new ArrayDeque<>();
        for (int r : roots) todo.push(r);
        while (!todo.isEmpty()) {
            int n = todo.pop();
            if (marked.add(n)) for (int m : refs.get(n)) todo.push(m);
        }
        // Sweep: whatever is not marked is garbage
        Set<Integer> garbage = new TreeSet<>(refs.keySet());
        garbage.removeAll(marked);
        System.out.println("marked (live): " + marked);
        System.out.println("garbage: " + garbage);
        // Time is proportional to live objects, and cycles are no problem
    }
}

import java.util.*;

public class Main {
    static class Obj {
        String name; int age;
        Obj(String n) { name = n; }
        public String toString() { return name + "(" + age + ")"; }
    }
    static List<Obj> eden = new ArrayList<>(), surv = new ArrayList<>(), old = new ArrayList<>();
    static final int THRESHOLD = 2, SURVIVOR_CAPACITY = 3;

    static void minorGc(String title, String... alive) {
        Set<String> live = new HashSet<>(Arrays.asList(alive));
        List<Obj> candidates = new ArrayList<>(surv);
        candidates.addAll(eden);
        List<Obj> next = new ArrayList<>();
        for (Obj o : candidates) {
            if (!live.contains(o.name)) continue;        // dead objects cost nothing
            o.age++;
            // too old, or survivor space full -> promoted to old generation
            if (o.age > THRESHOLD || next.size() >= SURVIVOR_CAPACITY) old.add(o);
            else next.add(o);
        }
        eden.clear(); surv = next;
        System.out.println(title + ": survivor=" + surv + " old=" + old);
    }

    public static void main(String[] args) {
        for (String n : "a b c d e".split(" ")) eden.add(new Obj(n));
        minorGc("GC1", "a", "b", "c", "d");       // d overflows survivor: premature promotion
        eden.add(new Obj("f")); eden.add(new Obj("g"));
        minorGc("GC2", "a", "b", "f", "g");
        eden.add(new Obj("h"));
        minorGc("GC3", "a", "f", "h");            // a passed the age threshold
    }
}

public class Main {
    // G1 aims for about 2048 regions: power of two between 1 and 32 MB
    static int regionMb(int heapMb) {
        int target = heapMb / 2048, size = 1;
        while (size * 2 <= target) size *= 2;
        return Math.max(1, Math.min(32, size));
    }

    public static void main(String[] args) {
        int[] heaps = {2048, 8192, 65536};
        for (int h : heaps) {
            System.out.println("heap " + h + " MB -> region " + regionMb(h) + " MB");
        }
        int region = regionMb(4096);                       // 2 MB regions
        System.out.println("heap 4096 MB: region " + region + " MB, humongous if >= "
                + (region * 1024 / 2) + " KB");
        int[] objectKb = {512, 1500, 3000, 20000};
        for (int kb : objectKb) {
            boolean humongous = kb >= region * 1024 / 2;   // half a region or more
            int regions = (kb + region * 1024 - 1) / (region * 1024);
            System.out.println("object " + kb + " KB: "
                    + (humongous ? "humongous, needs " + regions + " contiguous region(s)"
                                 : "normal allocation in Eden"));
        }
    }
}

import java.util.*;

public class Main {
    static int percentile(int[] sorted, double p) {
        int idx = (int) Math.ceil(p / 100.0 * sorted.length) - 1;
        return sorted[idx];
    }

    public static void main(String[] args) {
        int n = 1000;
        int[] withPause = new int[n], noPause = new int[n];
        List<Integer> spikes = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int base = 10 + (i % 7);               // normal latency 10..16 ms
            noPause[i] = base;
            withPause[i] = base;
            if (i % 67 == 0) {                     // a 300 ms GC pause hits this request
                withPause[i] += 300;
                spikes.add(i);
            }
        }
        System.out.println("spiked requests: " + spikes.size() + ", first at " + spikes.subList(0, 3));
        Arrays.sort(withPause); Arrays.sort(noPause);
        System.out.println("p50 = " + percentile(withPause, 50) + " ms (barely changes)");
        System.out.println("p99 without pauses = " + percentile(noPause, 99) + " ms");
        System.out.println("p99 with pauses    = " + percentile(withPause, 99) + " ms");
        // 1.5% of requests are slow, so p99 jumps while the average looks fine
    }
}

import java.util.*;

public class Main {
    // Static field = GC root: everything in it stays reachable forever
    static final Map<Integer, byte[]> LEAKY = new HashMap<>();

    static class Lru<K, V> extends LinkedHashMap<K, V> {
        final int max;
        Lru(int max) { super(16, 0.75f, true); this.max = max; }
        protected boolean removeEldestEntry(Map.Entry<K, V> e) { return size() > max; }
    }

    public static void main(String[] args) {
        Map<Integer, byte[]> bounded = new Lru<>(100);
        for (int requestId = 0; requestId < 1000; requestId++) {
            byte[] payload = new byte[1024];
            LEAKY.put(requestId, payload);        // never removed: a leak
            bounded.put(requestId, payload);      // oldest entries are evicted
        }
        System.out.println("leaky cache entries:   " + LEAKY.size()
                + " (~" + LEAKY.size() + " KB retained)");
        System.out.println("bounded cache entries: " + bounded.size()
                + " (~" + bounded.size() + " KB retained)");
        System.out.println("oldest key still in bounded cache: " + bounded.keySet().iterator().next());
    }
}

public class Main {
    public static void main(String[] args) {
        // Step 1: top -H -p <pid> shows the busiest thread ids in decimal
        long hotTid = 12345;
        // Step 2: jstack prints the same id in hex as nid=0x...
        String hex = "0x" + Long.toHexString(hotTid);
        System.out.println("top -H says TID " + hotTid + " -> search jstack for nid=" + hex);

        String[] jstack = {
            "\"GC Thread#0\" os_prio=0 nid=0x306f runnable",
            "\"http-worker-1\" #21 nid=0x3039 runnable",
            "\"main\" #1 nid=0x3001 waiting on condition"
        };
        for (String line : jstack) {
            if (line.contains("nid=" + hex)) {
                System.out.println("hot thread: " + line);
            }
        }
        // Repeat with 2-3 dumps a few seconds apart to see the same stack again
        System.out.println("12399 in hex is " + Long.toHexString(12399L));
    }
}

public class Main {
    public static void main(String[] args) {
        int podMb = 4096;
        // Default MaxRAMPercentage is 25: usually too small for a dedicated service
        System.out.println("default heap (25%): " + (int) (podMb * 0.25) + " MB");

        int heap = (int) (podMb * 0.70);                  // -XX:MaxRAMPercentage=70
        System.out.println("heap at 70%:        " + heap + " MB");

        // Rough non-heap estimate in MB
        int metaspace = 200, codeCache = 48, directBuffers = 128, gcStructures = 100;
        int threads = 150 * 1;                            // 150 threads x ~1 MB stack
        int nonHeap = metaspace + codeCache + directBuffers + gcStructures + threads;
        System.out.println("non-heap estimate:  " + nonHeap + " MB");

        int total = heap + nonHeap;
        System.out.println("heap + non-heap:    " + total + " MB of " + podMb + " MB");
        System.out.println(total <= podMb ? "fits with " + (podMb - total) + " MB spare"
                : "too big: the kernel OOM-killer would end the process (exit 137)");
    }
}
